const req = $('Webhook Mock').first().json;
const rota = (req.query?.rota || '').replace(/^\/+|\/+$/g, '');
const perfil = $input.first().json.usuario;
const usuario = perfil
  ? { id: perfil.id, nome: perfil.socialName || perfil.fullName, cargo: perfil.cargo }
  : null;

// sem token válido -> 401
if (!usuario) {
  return [{ json: { status: 401, body: { erro: 'Token invalido ou ausente' } } }];
}

// rota de identificação do usuário
if (rota === 'funcionarios/me') {
  return [{ json: { status: 200, body: usuario } }];
}

const dados = DADOS[rota];
if (!dados) {
  return [{ json: { status: 404, body: { erro: 'Rota nao encontrada: ' + rota } } }];
}

const permitidos = PERMISSOES[rota];
if (permitidos && !permitidos.includes(usuario.cargo)) {
  return [{ json: { status: 403, body: { erro: 'Seu cargo nao tem acesso a esta informacao' } } }];
}

return [{ json: { status: 200, body: dados } }];
